-- =====================================================================================
-- ATHLETE 3.0 · Catálogo para el motor híbrido, contratos 0.7.0 (Claude, 2026-11-08)
--
-- Aditiva:
--   1. Dos patrones de movimiento nuevos: 'locomotion' (remo, bici, carrera, natación) y 'mobility'.
--   2. Catálogo global 105 → 118 ejercicios y 16 → 22 equipos:
--      - cardio (modality 'cardio'): remo ergómetro, bici, correr, natación libre y técnica, caminata, cuerda, SkiErg;
--      - funcional: wall ball, burpees, salto al cajón, thruster;
--      - movilidad.
--      SQL generado por scripts/catalog-sql.ts desde catalog-data.ts (misma fuente que la app sin conexión).
-- Repite el cierre de privilegios de 0900. Aplicar junto con 20261109000100 (motor híbrido).
-- =====================================================================================

alter table athlete3.exercises drop constraint exercises_movement_pattern_valid;
alter table athlete3.exercises add constraint exercises_movement_pattern_valid check (movement_pattern is null or movement_pattern in (
  'squat', 'hinge', 'lunge', 'horizontal_push', 'vertical_push', 'horizontal_pull', 'vertical_pull',
  'chest_fly', 'shoulder_raise', 'elbow_flexion', 'elbow_extension', 'knee_extension', 'knee_flexion',
  'hip_extension', 'hip_abduction', 'hip_adduction', 'calf_raise', 'shrug', 'wrist',
  'core_anti_extension', 'core_flexion', 'core_rotation', 'carry', 'power', 'locomotion', 'mobility'));

